/// Raven `PM_SaberDeflectionForQuad`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:1116-1146`
pub fn PM_SaberDeflectionForQuad(quad: c_int) -> c_int {
    match quad {
        Q_B => LS_D1_B_,
        Q_BR => LS_D1_BR,
        Q_R => LS_D1__R,
        Q_TR => LS_D1_TR,
        Q_T => LS_D1_T_,
        Q_TL => LS_D1_TL,
        Q_L => LS_D1__L,
        Q_BL => LS_D1_BL,
        _ => LS_NONE,
    }
}

